    url: '#contacto',
    label: 'Agendar Demo Técnica →'
  };
} else {
  intent = 'fallback';
  outputHtml = `
    <p>He procesado su consulta: <em>"${rawMessage}"</em> mediante nuestro flujo de automatización en n8n.</p>
    <p>En <strong>DEVLANTIA</strong> desarrollamos ingeniería de software a medida adaptada a los requerimientos exactos de cada cliente.</p>
    <p class="text-xs text-brand-gray">Para orientarle con máxima precisión, elija la especialidad que mejor se adapte a su proyecto o solicite una llamada técnica:</p>
